package heimdall_test

import (
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/aarush323/heimdall-fixture-pay/internal/app"
)

// TestRefundReadIsScopedToItsMerchant has m-2 read a refund made by m-1 and wants 404.
func TestRefundReadIsScopedToItsMerchant(t *testing.T) {
	srv := httptest.NewServer(app.New(app.Config{}))
	defer srv.Close()

	do := func(method, path, merchant, key, body string) (int, []byte) {
		t.Helper()
		req, err := http.NewRequest(method, srv.URL+path, strings.NewReader(body))
		if err != nil {
			t.Fatal(err)
		}
		req.Header.Set("X-Merchant-ID", merchant)
		if key != "" {
			req.Header.Set("Idempotency-Key", key)
		}
		resp, err := srv.Client().Do(req)
		if err != nil {
			t.Fatal(err)
		}
		defer resp.Body.Close()
		raw, err := io.ReadAll(resp.Body)
		if err != nil {
			t.Fatal(err)
		}
		return resp.StatusCode, raw
	}

	status, body := do(http.MethodPost, "/payments", "m-1", "", `{"amount": 100, "currency": "USD"}`)
	if status != http.StatusCreated {
		t.Fatalf("create payment = %d: %s", status, body)
	}
	var pay map[string]any
	if err := json.Unmarshal(body, &pay); err != nil {
		t.Fatal(err)
	}
	paymentID, _ := pay["id"].(string)

	status, body = do(http.MethodPost, "/refunds", "m-1", "k1", `{"payment_id": "`+paymentID+`", "amount": 10}`)
	if status != http.StatusCreated {
		t.Fatalf("create refund = %d: %s", status, body)
	}
	var refund map[string]any
	if err := json.Unmarshal(body, &refund); err != nil {
		t.Fatal(err)
	}
	refundID, _ := refund["id"].(string)

	if status, body := do(http.MethodGet, "/refunds/"+refundID, "m-2", "", ""); status != http.StatusNotFound {
		t.Fatalf("m-2 read m-1's refund = %d, want 404: %s", status, body)
	}
}
